package rules; public final class ContentOption{private final String text;private final boolean nocase;public ContentOption(String text,boolean nocase){this.text=text==null?"":text;this.nocase=nocase;}public String text(){return text;}public boolean nocase(){return nocase;}public boolean matches(byte[] payload){if(payload==null)return false;String h=new String(payload,java.nio.charset.StandardCharsets.ISO_8859_1);return nocase?h.toLowerCase(java.util.Locale.ROOT).contains(text.toLowerCase(java.util.Locale.ROOT)):h.contains(text);}}
